namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(
        IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();

        foreach (var item in items)
        {
            if (!CanReplenish(item))
                continue;

            int quantity = ApplySeason(
                CalculateBaseQuantity(item.ReorderPoint - Available(item)),
                season);
            var sku = item.Sku;

            if (quantity <= 0 || string.IsNullOrEmpty(sku))
                continue;

            bool placed = supplier.PlaceOrder(sku, quantity);
            plan.Add(FormatResult(sku, quantity, placed));
        }

        return plan;
    }

    private static int Available(StockItem item) => item.OnHand - item.Reserved;

    private static bool CanReplenish(StockItem item) =>
        item.OnHand >= 0 && Available(item) <= item.ReorderPoint;

    private static int CalculateBaseQuantity(int deficit) => deficit switch
    {
        <= 0 => 0,
        < 10 => 10,
        < 100 => deficit,
        _ => deficit + 50
    };

    private static int ApplySeason(int quantity, int season) =>
        season == 4 && quantity > 0 ? (int)(quantity * 1.5) :
        season == 1 ? quantity / 2 : quantity;

    private static string FormatResult(string sku, int quantity, bool placed) =>
        !placed ? $"{sku}:FAILED" :
        quantity > 200 ? $"{sku}:LARGE:{quantity}" : $"{sku}:{quantity}";
}
